      },
      "inputs": {
        "entryPointId": "c98beac7-90dc-471d-9506-d17fd006aad2",
        "isDefaultEntryPoint": true
      }
    },
    {
      "id": "transformBooks",
      "type": "core.action.transform",
      "typeVersion": "1.0",
      "display": {
        "label": "Curate Reading List"
      },
      "inputs": {
        "collection": "$vars.catalog",
        "operations": [
          {
            "id": "op1",
            "type": "filter",
            "config": {
              "operation": "and",
              "filters": [
                {
                  "id": "f1",
                  "field": "difficulty",
                  "condition": "greater_than",
                  "value": 5
                },
                {
                  "id": "f2",
                  "field": "pages",
                  "condition": "less_than",
                  "value": 600
                }
              ]
            }
          },
          {
            "id": "op2",
            "type": "map",
            "config": {
              "keepOriginalFields": false,
              "mappings": [
                {
                  "id": "m1",
                  "field": "title",
                  "transformation": "uppercase",
                  "renameTo": ""
                },
                {
                  "id": "m2",
                  "field": "author",
                  "transformation": "copy",
                  "renameTo": ""
                }
              ]
            }
          }
        ]
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the transform",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the transform fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "end1",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "End"
      },
      "inputs": {},
      "outputs": {
        "readingList": {
          "source": "=js:$vars.transformBooks.output"
        }
      }
    }
  ],
  "edges": [
    {
      "id": "e1",
      "sourceNodeId": "start",
      "sourcePort": "output",
      "targetNodeId": "transformBooks",
      "targetPort": "input"
    },
    {
      "id": "e2",
      "sourceNodeId": "transformBooks",
      "sourcePort": "output",
      "targetNodeId": "end1",
      "targetPort": "input"
    }
  ],
